-- 221: Original BrillaPrep WASSCE BrillaPrep transitional Sculpture beta content blueprint questions, part 9.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_221_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_221_guard;
INSERT INTO _migration_221_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_033' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_7' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How can a sculptor test whether an apparently balanced form is physically stable?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Increase the plinth height until the composition appears lighter","B. Check that the projected centre of gravity remains within the support area under expected conditions","C. Compare only the visible colours on opposite sides of the work","D. Assume bilateral symmetry guarantees stability on any base"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Physical equilibrium depends on mass and support geometry, not visual balance alone. The base, attachment and foreseeable contact should be assessed for the intended display environment. Therefore the correct answer is B: Check that the projected centre of gravity remains within the support area under expected conditions.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_7' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_033' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_221_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_034' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_7' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is a protective surface finish tested on a concealed area or sample first?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It may alter colour, gloss, adhesion or the underlying material","B. The trial identifies how heavy a coat can conceal surface variation, even if gloss and reversibility are not assessed","C. The trial selects the shortest touch-dry time, which is sufficient evidence that the finish will remain bonded after curing","D. The trial confirms catalogue colour; adhesion and material compatibility are already assured when the label names the substrate"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A trial reveals visual and chemical compatibility before an irreversible application. It also helps the maker refine preparation, application thickness and drying conditions. Therefore the correct answer is A: It may alter colour, gloss, adhesion or the underlying material.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_7' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_034' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_221_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_035' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_7' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How should a plinth and lighting support presentation of a sculpture?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Provide stable viewing conditions that reinforce scale, form and intended emphasis","B. Aim strong light from one direction without checking glare or lost detail","C. Place the sculpture above normal sight lines regardless of intended viewpoint","D. Use the narrowest plinth so the work appears to float despite instability"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Presentation affects safety and meaning. Plinth dimensions, sight lines, background and controlled light should reveal mass, texture and negative space while respecting the intended viewpoint. Therefore the correct answer is A: Provide stable viewing conditions that reinforce scale, form and intended emphasis.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_7' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_035' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_221_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_036' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_8' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which information belongs in a concise professional artist brochure?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Only a price list and decorative background without identifying the artist","B. A copied biography of another sculptor whose style appears similar","C. Every process photograph taken, printed without selection or captions","D. Artist name, contact details, short statement, selected work images with captions, and relevant exhibition or studio information"]' AND q.correct_answer IS 'D' AND q.explanation IS 'An artist brochure is an edited communication tool. Clear identity, accessible contact, a concise practice statement and accurately captioned images help an audience understand and follow up on the work. Therefore the correct answer is D: Artist name, contact details, short statement, selected work images with captions, and relevant exhibition or studio information.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_036' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_033', 'topic_was_sculpture_b004_7', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'How can a sculptor test whether an apparently balanced form is physically stable?', 'multiple_choice', NULL, '["A. Increase the plinth height until the composition appears lighter","B. Check that the projected centre of gravity remains within the support area under expected conditions","C. Compare only the visible colours on opposite sides of the work","D. Assume bilateral symmetry guarantees stability on any base"]', 'B', 'Physical equilibrium depends on mass and support geometry, not visual balance alone. The base, attachment and foreseeable contact should be assessed for the intended display environment. Therefore the correct answer is B: Check that the projected centre of gravity remains within the support area under expected conditions.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_7', 'Explain', 'AO3', NULL, NULL, 'board_waec');
