INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_035', 'topic_was_sculpture_b004_7', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'How should a plinth and lighting support presentation of a sculpture?', 'multiple_choice', NULL, '["A. Provide stable viewing conditions that reinforce scale, form and intended emphasis","B. Aim strong light from one direction without checking glare or lost detail","C. Place the sculpture above normal sight lines regardless of intended viewpoint","D. Use the narrowest plinth so the work appears to float despite instability"]', 'A', 'Presentation affects safety and meaning. Plinth dimensions, sight lines, background and controlled light should reveal mass, texture and negative space while respecting the intended viewpoint. Therefore the correct answer is A: Provide stable viewing conditions that reinforce scale, form and intended emphasis.', 'medium', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_7', 'Explain', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_036', 'topic_was_sculpture_b004_8', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'Which information belongs in a concise professional artist brochure?', 'multiple_choice', NULL, '["A. Only a price list and decorative background without identifying the artist","B. A copied biography of another sculptor whose style appears similar","C. Every process photograph taken, printed without selection or captions","D. Artist name, contact details, short statement, selected work images with captions, and relevant exhibition or studio information"]', 'D', 'An artist brochure is an edited communication tool. Clear identity, accessible contact, a concise practice statement and accurately captioned images help an audience understand and follow up on the work. Therefore the correct answer is D: Artist name, contact details, short statement, selected work images with captions, and relevant exhibition or studio information.', 'hard', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_8', 'Identify', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-visual-arts-beta-004', 'automated_beta', 'beta', 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.', 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf', 0, 1 FROM questions WHERE id IN ('q_was_sculpture_b004_033', 'q_was_sculpture_b004_034', 'q_was_sculpture_b004_035', 'q_was_sculpture_b004_036');
